226	/// POST /versions：把当前数据集固化为不可变快照。
227	async fn save_version(State(state): State<AppState>) -> Json<SaveResponse> {
228	    let mut store: MutexGuard<Store> = state.store.lock().unwrap();
229	    let version = store.snapshots.len() as u64 + 1;
230	    let records = store
231	        .dataset
232	        .iter()
233	        .map(|(key, fields)| (key.clone(), Value::Object(fields.clone())))
234	        .collect();
235	    let total = store.dataset.len();
236	    store.snapshots.push(Snapshot { version, records });
237	    Json(SaveResponse { version, total })
238	}
